const e=[{id:"sv-2-1041",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:'Why does the book describe the normal distribution as "the most commonly used and abused"?',options:["It applies only to attribute data but is used for continuous data","It is often assumed for data without first checking whether they are normal","It requires very large samples that projects rarely have","Its two parameters are too difficult to estimate from sample data"],answer:1,hint:"Think about the habit the book warns against before using normal-based tools.",steps:[{title:"Key idea",body:"Many tools assume normality, and many business processes are not normal (p. 154)."},{title:"Apply to the stem",body:"The 'abuse' is assuming normality without testing it, so the answers from those tools can be wrong."}],final:"Abused = assumed without checking → answer **B**",whyWrong:["Incorrect — the normal distribution is a model for continuous data, not attribute data.","","Incorrect — the book's caution about large samples concerns the normality test, not the distribution.","Incorrect — the mean and standard deviation are the easiest statistics to estimate."],bookRef:"Book pp. 152–154"},{id:"sv-2-1042",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"A measured value has a **Z-score of 0**. Where does it lie?",options:["At the lower specification limit","Exactly at the mean of the distribution","One standard deviation below the mean","At the smallest value in the data"],answer:1,hint:"Z counts standard deviations away from the mean.",steps:[{title:"Key idea",body:"Z is the number of standard deviations between a value and the mean (p. 152)."},{title:"Apply to the stem",body:"Zero standard deviations away means the value **is** the mean."}],final:"Z = 0 → at the mean → answer **B**",whyWrong:["Incorrect — specification limits come from the customer; Z = 0 says nothing about them.","","Incorrect — that position has a Z-score of −1.","Incorrect — the minimum lies well below the mean, so its Z-score is negative."],bookRef:"Book p. 152"},{id:"sv-2-1043",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"A delivery time has a **Z-score of −1.5**. What does this mean?",options:["It lies 1.5 standard deviations above the mean","1.5% of delivery times are shorter than it","It lies 1.5 hours below the mean","It lies 1.5 standard deviations below the mean"],answer:3,hint:"Read the sign and the size of Z separately.",steps:[{title:"Key idea",body:"Size of Z = how many standard deviations from the mean; sign = which side."},{title:"Apply to the stem",body:"−1.5 → one and a half standard deviations **below** the mean."},{title:"Eliminate look-alikes",body:"Reading Z as a percentage or in data units are the two classic mis-reads."}],final:"−1.5 → 1.5 SD below the mean → answer **D**",whyWrong:["Incorrect — the negative sign places the value below the mean, not above it.","Incorrect — a Z-score is a distance, not a proportion; the share comes from a Z table.","Incorrect — a Z-score has no units; it is measured in standard deviations, not hours.",""],trap:"A Z-score is never a percentage of data; one vendor answer key gets this wrong.",bookRef:"Book p. 152"},{id:"sv-2-1044",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"What is the MAIN reason for converting a normally distributed value into a Z-score?",options:["So that non-normal data become normally distributed","So that one standard normal table can give the area for any normal process","So that outliers are removed before the analysis","So that the standard deviation of the data can be estimated"],answer:1,hint:"Every normal curve can be turned into one reference curve.",steps:[{title:"Key idea",body:"Any normal distribution converts to the standard normal (μ = 0, σ = 1) with Z (p. 152)."},{title:"Apply to the stem",body:"After conversion, a single table gives areas, so one look-up works for every process."}],final:"Z lets one table serve every normal curve → answer **B**",whyWrong:["Incorrect — standardising rescales the data; it does not change their shape.","","Incorrect — standardising keeps every value; outliers are handled by investigation, not by Z.","Incorrect — the standard deviation is needed to calculate Z, not produced by it."],bookRef:"Book pp. 152–153"},{id:"sv-2-1045",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"A specification limit lies further from the mean, so its Z-value is larger. What happens to the expected proportion of output beyond that limit?",options:["It becomes larger","It becomes smaller","It stays the same, because Z does not affect the area","It becomes zero once Z passes 3"],answer:1,hint:"Picture the tail of the bell beyond a line that moves outward.",steps:[{title:"Key idea",body:"The area beyond a limit is the expected proportion outside it (p. 153)."},{title:"Apply to the stem",body:"Moving the limit outward (larger Z) cuts off a thinner tail, so the proportion falls."}],final:"Larger Z → smaller tail → fewer defects → answer **B**",whyWrong:["Incorrect — this reverses the relationship; a limit further out leaves less of the tail beyond it.","","Incorrect — the Z-value is exactly what fixes the tail area in the table.","Incorrect — the tails never reach zero; beyond 3σ the area is very small but not zero."],bookRef:"Book pp. 153, 222"},{id:"sv-2-1046",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"What type of statistical test is the **Anderson-Darling** test?",options:["A goodness-of-fit test","A test for equal variances","A test for a difference in means","A test of independence for counts"],answer:0,hint:"It checks how well the data match a model distribution.",steps:[{title:"Key idea",body:"Book p. 155: AD compares the actual data with a normal curve of the same mean and SD — 'observed minus expected'."},{title:"Apply to the stem",body:"Comparing observed data with a fitted model is a **goodness-of-fit** test."}],final:"AD = goodness of fit → answer **A**",whyWrong:["","Incorrect — equal variances are tested with F, Bartlett's or Levene's test.","Incorrect — means are compared with t-tests or ANOVA.","Incorrect — independence of counts is tested with a chi-square test."],bookRef:"Book p. 155"},{id:"sv-2-1047",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"In Anderson-Darling output, what does a **larger AD (A-squared) statistic** indicate?",options:["The data fit the normal distribution more closely","The sample contains more data points","The process standard deviation is larger","The data depart further from the fitted normal distribution"],answer:3,hint:"AD measures the gap between observed and expected.",steps:[{title:"Key idea",body:"AD sums the differences between the data and a normal curve with the same mean and SD (p. 155)."},{title:"Apply to the stem",body:"Bigger gaps → bigger AD → smaller p-value → stronger evidence of non-normality."}],final:"Large AD = poor fit → answer **D**",whyWrong:["Incorrect — this reverses the statistic; a close fit gives a small AD value and a large p-value.","Incorrect — the sample size is reported as N; AD measures the misfit.","Incorrect — spread is reported as StDev; a wide normal process can still have a small AD.",""],bookRef:"Book p. 155"},{id:"sv-2-1048",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"How do normally distributed data appear on a **normal probability plot**?",options:["As points lying close to a straight line","As points forming a symmetric bell shape","As points spread evenly in a horizontal band","As points forming two separate clusters"],answer:0,hint:"The plot's scale is built so that normal data straighten out.",steps:[{title:"Key idea",body:"Book p. 155: on a normal probability plot, normal data fall on a **straight line**."},{title:"Apply to the stem",body:"Bends away from the line show where the data differ from normal."}],final:"Normal → straight line → answer **A**",whyWrong:["","Incorrect — the bell shape is what a histogram shows, not a probability plot.","Incorrect — a horizontal band is what a stable time series plot shows.","Incorrect — two clusters suggest a bimodal mixture, a sign of non-normality."],bookRef:"Book p. 155"},{id:"sv-2-1049",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"On a Minitab normal probability plot, each data value is plotted against what?",options:["The order in which the value was collected","The number of values in its interval","The value of a second continuous variable","The cumulative percent expected if the data were normal"],answer:3,hint:"The vertical axis of a probability plot is labelled 'Percent'.",steps:[{title:"Key idea",body:"A probability plot pairs each ordered value with its cumulative percent on a normal-probability scale."},{title:"Apply to the stem",body:"If the data are normal, these pairs line up straight."}],final:"Value vs expected cumulative percent → answer **D**",whyWrong:["Incorrect — plotting against collection order is a time series plot.","Incorrect — counts per interval are the bars of a histogram.","Incorrect — plotting one variable against another is a scatter plot.",""],bookRef:"Book p. 155"},{id:"sv-2-1050",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"What do the curved **confidence bands** on a Minitab normal probability plot help the analyst judge?",options:["Whether the process output meets its specification limits","Whether the points stray further from the line than chance would explain","Whether the measurement system is adequate for the study","Whether the process mean has shifted over time"],answer:1,hint:"The bands show how far random samples from a normal population usually wander.",steps:[{title:"Key idea",body:"Points inside the bands are consistent with normal data; points outside show a real departure."},{title:"Eliminate look-alikes",body:"Specification, gauge and time questions belong to capability, MSA and control charts."}],final:"Bands = allowance for chance around the line → answer **B**",whyWrong:["Incorrect — meeting the specification is a capability question, answered against the limits.","","Incorrect — gauge adequacy is judged with a Gage R&R study.","Incorrect — shifts over time are seen on a time series plot or control chart."],bookRef:"Book p. 155"},{id:"sv-2-1051",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"How does the book view **non-normal data** found in the Measure phase?",options:["As a sign that the data were collected wrongly","As useful information that often points to special causes","As a reason to stop and restart the project","As proof that the process is out of statistical control"],answer:1,hint:'The book says non-normal data are "not a bad thing".',steps:[{title:"Key idea",body:"Book pp. 157–158: non-normal data are not bad; when data should be normal but are not, there are probably **special causes** to find."},{title:"Apply to the stem",body:"So non-normality is a clue to investigate, not a failure."}],final:"Non-normal = clue, not failure → answer **B**",whyWrong:["Incorrect — non-normal shapes are common in transactional processes; they do not imply bad collection.","","Incorrect — the book says do not panic; the project continues with a different approach.","Incorrect — stability is judged on a control chart; shape alone proves nothing about control."],bookRef:"Book pp. 157–158"},{id:"sv-2-1052",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"According to the book, how should the baseline capability be expressed in Measure when the data are **not normal**?",options:["By using the observed performance, such as the actual share outside the specification","By calculating Z from the mean and standard deviation as usual","By deleting values until the data pass a normality test","By reporting the Anderson-Darling p-value as the capability"],answer:0,hint:"If the normal model does not fit, report what actually happened.",steps:[{title:"Key idea",body:"Book p. 158: for capability in Measure, **use observed performance** unless the data are normal."},{title:"Eliminate look-alikes",body:"Normal-based Z is invalid here; deleting data or quoting a p-value is not capability."}],final:"Non-normal → observed performance → answer **A**",whyWrong:["","Incorrect — Z-based estimates assume normality, which these data have failed.","Incorrect — deleting data to force normality hides the special causes the data reveal.","Incorrect — the p-value judges the shape; it is not a measure of meeting the specification."],bookRef:"Book p. 158"},{id:"sv-2-1053",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which type of data can follow a **normal distribution**?",options:["Counts of errors on each invoice","Pass or fail results for each unit","Ranked satisfaction categories from a survey","Continuous measurements such as fill weight in grams"],answer:3,hint:"The normal curve is smooth and continuous.",steps:[{title:"Key idea",body:"The normal distribution is the most useful **continuous** model (p. 152)."},{title:"Eliminate look-alikes",body:"Counts, pass/fail results and ranks are discrete or attribute data."}],final:"Normal fits continuous data → answer **D**",whyWrong:["Incorrect — counts of defects per unit are discrete and usually follow a Poisson distribution.","Incorrect — pass/fail results are attribute data and follow a binomial distribution.","Incorrect — ranked categories are ordinal data and cannot be normal.",""],bookRef:"Book p. 152"},{id:"sv-2-1054",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:`In the book's guidance, what should decide whether a data distribution is "good" or "bad"?`,options:["Whether it passes an Anderson-Darling test","Its shape in relation to the intent of the project","Whether its mean is equal to its median","Whether it has a single peak"],answer:1,hint:"The book says there is no good or bad shape in itself.",steps:[{title:"Key idea",body:"Book p. 154: there is no 'good' or 'bad' distribution — look at it in relation to the **intent of your project**."},{title:"Apply to the stem",body:"A skewed time that piles up near zero may be exactly what a speed project wants."}],final:"Judge shape against project intent → answer **B**",whyWrong:["Incorrect — passing or failing a normality test only describes the shape; it is not a verdict on quality.","","Incorrect — equal mean and median only show symmetry, not whether the shape is desirable.","Incorrect — a single peak is not good in itself; the project goal sets what is desirable."],bookRef:"Book p. 154"},{id:"sv-2-1055",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which feature of the normal curve explains why its mean and median are equal?",options:["Its tails extend without ever touching the axis","It is defined by exactly two parameters","Its total area under the curve equals one","It is symmetric about its centre"],answer:3,hint:"Which property would fail for a skewed distribution?",steps:[{title:"Key idea",body:"A symmetric curve has equal halves, so the middle value (median) and the balance point (mean) coincide."},{title:"Eliminate look-alikes",body:"Skewed curves also have area one and two parameters can describe them, yet their mean and median differ."}],final:"Symmetry → mean = median → answer **D**",whyWrong:["Incorrect — endless tails describe the reach of the curve, not why the centre measures match.","Incorrect — two parameters set location and spread; equality of mean and median comes from symmetry.","Incorrect — every probability distribution has a total area of one, including skewed ones.",""],bookRef:"Book p. 152"},{id:"sv-2-1056",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"Two processes are measured in different units: latency in milliseconds and repair time in hours. Why can Z-scores compare how unusual a reading is in each?",options:["Because Z-scores convert both readings into percentages of defects","Because Z-scores convert both readings into the same physical unit","Because each Z-score is expressed in standard deviations of its own process","Because Z-scores remove the variation from both processes"],answer:2,hint:"What happens to the units when a difference is divided by the standard deviation?",steps:[{title:"Key idea",body:"Z divides the distance from the mean by the standard deviation, so the units cancel (p. 152)."},{title:"Apply to the stem",body:"Each reading becomes 'so many SDs from its own mean', which can be compared directly."}],final:"Z is unit-free → comparable → answer **C**",whyWrong:["Incorrect — a Z-score is a distance, not a percentage; the defect share comes from a table.","Incorrect — Z has no physical unit at all; the units cancel out.","","Incorrect — Z uses each process's variation as the yardstick; it does not remove it."],bookRef:"Book p. 152"},{id:"sv-2-1057",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Why are **cycle-time** data often non-normal by nature?",options:["Time cannot be negative, so the data are bounded at zero with a long right tail","Time is an attribute measure, so it cannot follow a continuous curve","Time data always contain measurement errors from the clock","Time data are always collected in subgroups of five"],answer:0,hint:"The book jokes about needing a flux capacitor.",steps:[{title:"Key idea",body:"Book p. 154: time cannot be negative ('without a flux capacitor'), so cycle times are usually **bounded at zero and skewed right**."},{title:"Apply to the stem",body:"A hard floor with no ceiling stretches the right tail."}],final:"Bounded at zero → right skew → answer **A**",whyWrong:["","Incorrect — time is continuous data; its skew comes from the zero bound, not its data type.","Incorrect — clock error is an MSA issue; it does not explain the typical skewed shape.","Incorrect — subgrouping is a sampling choice and does not make a distribution skewed."],bookRef:"Book p. 154"},{id:"sv-2-1058",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"What does a **standard normal (Z) table** provide?",options:["The Z value of any sample mean from the raw data","The area under the curve that goes with a given Z value","The critical p-value for a normality test","The standard deviation that goes with a given mean"],answer:1,hint:"You enter the table with Z and read off an area.",steps:[{title:"Key idea",body:"Book p. 153: after converting to Z, look up the **area** in a standard normal table."},{title:"Apply to the stem",body:"That area is the proportion of output beyond (or up to) the value."}],final:"Z table: Z in, area out → answer **B**",whyWrong:["Incorrect — Z is calculated from the value, mean and SD; the table starts from Z.","","Incorrect — the normality p-value comes from the Anderson-Darling test, not a Z table.","Incorrect — the mean and SD are independent parameters; no table links them."],bookRef:"Book p. 153"},{id:"sv-2-1059",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"In a Minitab graphical summary, the data show a **skewness of +1.8**. What does this indicate?",options:["A longer tail on the right-hand side","A longer tail on the left-hand side","A flatter peak than a normal curve","Two separate peaks in the data"],answer:0,hint:"The sign of skewness points to the longer tail.",steps:[{title:"Key idea",body:"Skewness near 0 = symmetric; positive = right tail; negative = left tail."},{title:"Apply to the stem",body:"+1.8 is clearly positive → right-skewed, typical of times bounded at zero."}],final:"Positive skew → right tail → answer **A**",whyWrong:["","Incorrect — a left tail gives a negative skewness value.","Incorrect — peakedness and tail weight are described by kurtosis, not skewness.","Incorrect — two peaks are a bimodal shape; skewness measures lopsidedness."],bookRef:"Book pp. 154–155"},{id:"sv-2-1060",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:'The book says data with an Anderson-Darling p-value above 0.05 are "normal enough for most purposes". What does this mean?',options:["The data have been proven to come from a normal population","The process meets its customer specification most of the time","The process is stable enough for a control chart to be skipped","There is no evidence against normality, so normal-based tools may be used"],answer:3,hint:"'Fail to reject' is a practical green light, not a proof.",steps:[{title:"Key idea",body:"p > 0.05 → fail to reject H₀ (data normal) → treat as normal (p. 156)."},{title:"Eliminate look-alikes",body:"Proof, capability and stability are all claims a normality test cannot make."}],final:"Normal enough = fail to reject → use normal tools → answer **D**",whyWrong:["Incorrect — a test can only fail to reject H₀; it never proves normality.","Incorrect — normality describes the shape, not performance against the specification.","Incorrect — stability is a separate check made with a control chart.",""],bookRef:"Book p. 156"},{id:"sv-2-1061",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"The Anderson-Darling test shows that order-delivery times are normal. What does this tell the team about meeting the **48-hour target**?",options:["That the process meets the 48-hour target","That the process is stable over time","Nothing directly; performance against the target must be assessed separately","That the process is centred on the target"],answer:2,hint:"A normality test compares the data with a normal curve, not with a specification.",steps:[{title:"Key idea",body:"AD tests only the **shape** of the data (p. 155)."},{title:"Apply to the stem",body:"Meeting a target is a capability question; normality only decides which capability method fits."}],final:"Normality ≠ capability → answer **C**",whyWrong:["Incorrect — a normal process can sit largely beyond a target; shape says nothing about the limit.","Incorrect — stability is shown by a control chart, not by a normality test.","","Incorrect — the test fits a normal curve at the data's own mean, whatever the target is."],bookRef:"Book pp. 155, 221"},{id:"sv-2-1062",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about the **shape of a normal distribution** is CORRECT?",options:["Changing the standard deviation changes its width but not its centre","Changing the mean changes its width but not its centre","Its median is always larger than its mean","It can have more than one peak"],answer:0,hint:"One parameter sets location, the other sets spread.",steps:[{title:"Key idea",body:"Normal curve: mean = location, standard deviation = spread (p. 152)."},{title:"Eliminate look-alikes",body:"The other statements swap the parameters or describe skewed or bimodal shapes."}],final:"SD changes width only → answer **A**",whyWrong:["","Incorrect — the mean moves the centre; the width is set by the standard deviation.","Incorrect — median above mean describes a left-skewed shape; in a normal curve they are equal.","Incorrect — more than one peak is a bimodal shape, often mixed process streams."],bookRef:"Book p. 152"},{id:"sv-2-1063",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about **Z-scores** is CORRECT?",options:["A Z-score gives the proportion of data beyond the value","A Z-score is expressed in the same units as the data","A negative Z-score shows that the value lies below the mean","A Z-score can only be calculated for values inside the specification"],answer:2,hint:"Z = distance from the mean in SDs; the sign gives the side.",steps:[{title:"Key idea",body:"Z = (value − mean) ÷ SD, so values below the mean give negative Z."},{title:"Eliminate look-alikes",body:"Proportion and units are the two common mis-readings of Z."}],final:"Negative Z → below the mean → answer **C**",whyWrong:["Incorrect — Z is a distance in SDs; the proportion is read from a Z table.","Incorrect — dividing by the SD cancels the units, so Z is unit-free.","","Incorrect — Z is often calculated for the specification limits themselves."],trap:"Z is not a proportion — the proportion comes from the table.",bookRef:"Book p. 152"},{id:"sv-2-1064",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about a **normal probability plot** is CORRECT?",options:["It provides the p-value that decides normality","It shows where the data depart from normal, such as in one tail","It shows the order in which the data were collected","It can only be used when the sample has fewer than 30 values"],answer:1,hint:"The test answers 'whether'; the plot answers 'where'.",steps:[{title:"Key idea",body:"Book p. 155: points that bend away from the straight line show **where** the data differ from normal."},{title:"Eliminate look-alikes",body:"The p-value belongs to AD; time order belongs to a time series plot."}],final:"Plot shows where the misfit is → answer **B**",whyWrong:["Incorrect — the p-value comes from the Anderson-Darling test printed beside the plot.","","Incorrect — collection order is shown by a time series plot.","Incorrect — the plot works for any sample size and is relied on more as N grows."],bookRef:"Book p. 155"},{id:"sv-2-1065",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which statement about **non-normal data** in Lean Six Sigma projects is CORRECT?",options:["They show that the measurement system has failed","They must always be transformed before any graph is drawn","They prove that the process is out of statistical control","They are common in transactional processes and often contain clues to special causes"],answer:3,hint:"Recall the book's 'do not panic' advice.",steps:[{title:"Key idea",body:"Book p. 157: non-normal data are common in the transactional world and are not a bad thing."},{title:"Apply to the stem",body:"When data should be normal but are not, special causes are probably present (p. 158)."}],final:"Common, and a clue to special causes → answer **D**",whyWrong:["Incorrect — a gauge problem is found with MSA; non-normal shapes are normal in service work.","Incorrect — graphs are drawn on the raw data; transformation is a later, optional method.","Incorrect — control is judged on a control chart, not from the shape of a histogram.",""],bookRef:"Book pp. 157–158"},{id:"sv-2-1066",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about the **area under a normal curve** is CORRECT?",options:["The total area depends on the size of the standard deviation","Half of the total area lies within ±1 standard deviation","The total area is 1, so any area can be read as a proportion of output","The area beyond +3 standard deviations is exactly zero"],answer:2,hint:"The whole curve represents all of the output.",steps:[{title:"Key idea",body:"Book p. 153: the area between two points equals the proportion of the distribution between them."},{title:"Apply to the stem",body:"Because the whole area is 1 (100%), every part of it is a share of output."}],final:"Total area = 1 → area = proportion → answer **C**",whyWrong:["Incorrect — the total area is always 1; the SD only changes how it is spread.","Incorrect — about 68% lies within ±1 SD; half lies on each side of the mean.","","Incorrect — it is very small (about 0.135%) but never zero."],bookRef:"Book p. 153"},{id:"sv-2-1067",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about using **Z to estimate the proportion of defects** is CORRECT?",options:["It is valid for any distribution shape","It needs the median and range rather than the mean and standard deviation","It gives the number of defects per unit directly","It is valid only when the data are approximately normal"],answer:3,hint:"Where do Z-table areas come from?",steps:[{title:"Key idea",body:"The Z method converts to the standard normal and reads its area (p. 153)."},{title:"Apply to the stem",body:"If the data are not normal, those areas do not describe them — check normality first (p. 221)."}],final:"Z estimates need normal data → answer **D**",whyWrong:["Incorrect — Z-table areas come from the normal curve, so skewed data give wrong answers.","Incorrect — Z is built from the mean and standard deviation.","Incorrect — Z leads to a proportion of units beyond a limit, not a count of defects per unit.",""],bookRef:"Book pp. 153, 221"},{id:"sv-2-1068",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

A Z-score is the number of [?] that a value lies from the mean.`,options:["interquartile ranges","percentiles","standard deviations","variances"],answer:2,hint:"Z = (value − mean) divided by …?",steps:[{title:"Key idea",body:"Book p. 152: a Z-score tells you **how many standard deviations** a value is from the mean."},{title:"Eliminate look-alikes",body:"IQR, percentiles and variance are other spread or position measures."}],final:"Z counts standard deviations → answer **C**",whyWrong:["Incorrect — the interquartile range measures the spread of the middle 50% and is used for box-plot outliers.","Incorrect — percentiles give the share of data below a value, which is found from Z, not equal to it.","","Incorrect — the variance is the squared standard deviation, in squared units, and is not the Z yardstick."],bookRef:"Book p. 152"},{id:"sv-2-1069",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:2,stem:`Identify the missing word(s) in the following sentence.

The Anderson-Darling test compares the observed data with the [?] values from a normal distribution that has the same mean and standard deviation.`,options:["expected","maximum","specified","target"],answer:0,hint:"The book's shorthand is 'observed minus …'.",steps:[{title:"Key idea",body:"Book p. 155: AD is a goodness-of-fit test — 'observed minus **expected**'."},{title:"Apply to the stem",body:"Expected values come from a normal curve fitted with the data's own mean and SD."}],final:"Observed vs expected → answer **A**",whyWrong:["","Incorrect — maximum values describe the range of the data, not the fitted normal curve.","Incorrect — specified values are customer limits; AD does not use the specification.","Incorrect — a target is a customer or business goal; the AD test ignores it."],bookRef:"Book p. 155"},{id:"sv-2-1070",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

Calculating Z-scores converts any normal distribution into the [?] normal distribution.`,options:["cumulative","inverse","skewed","standard"],answer:3,hint:"Mean 0, standard deviation 1.",steps:[{title:"Key idea",body:"Book p. 152: any normal distribution converts to the **standard normal** (μ = 0, σ = 1) by using Z."},{title:"Apply to the stem",body:"That is why one table serves every normal process."}],final:"Z → standard normal → answer **D**",whyWrong:["Incorrect — 'cumulative' describes adding areas up to a point, not the converted distribution.","Incorrect — 'inverse' describes finding a value from a probability, not the converted distribution.","Incorrect — a normal distribution is symmetric; converting it cannot make it skewed.",""],bookRef:"Book p. 152"},{id:"sv-2-1071",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

The [?] of a normal distribution determines how wide and flat the bell curve is.`,options:["mean","median","mode","standard deviation"],answer:3,hint:"Location versus spread.",steps:[{title:"Key idea",body:"A normal curve has two parameters (p. 152): the mean sets location, the **standard deviation** sets spread."},{title:"Eliminate look-alikes",body:"Mean, median and mode all coincide at the centre of a normal curve."}],final:"Width = standard deviation → answer **D**",whyWrong:["Incorrect — the mean sets where the curve is centred, not how wide it is.","Incorrect — the median equals the mean in a normal curve and also marks the centre.","Incorrect — the mode is the peak position, which is the centre of a normal curve.",""],bookRef:"Book p. 152"},{id:"sv-2-1072",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:3,stem:`Identify the missing word(s) in the following sentence.

The book's rule of thumb is that if N is greater than [?] and the normal probability plot looks normal, the data probably are normal.`,options:["10","30","100","1,000"],answer:2,hint:"The rule of thumb sits with the large-sample caution on p. 157.",steps:[{title:"Key idea",body:"Book p. 157: with very large samples AD becomes very sensitive — if **N > 100** and the plot looks normal, it probably is."},{title:"Eliminate look-alikes",body:"10 (box plot) and 30 (CLT) are other rules of thumb from different topics."}],final:"N > 100 rule → answer **C**",whyWrong:["Incorrect — 10 is the book's minimum for drawing a box plot, not the AD rule of thumb.","Incorrect — 30 is the usual sample size quoted for the central limit theorem.","","Incorrect — the book's threshold is much lower; AD is already over-sensitive well below 1,000."],bookRef:"Book p. 157"},{id:"sv-2-1073",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:1,stem:"Which is NOT a property of a normal curve?",options:["It is symmetric about its mean","It is bounded at zero on the left-hand side","Its total area under the curve equals one","Its tails extend indefinitely in both directions"],answer:1,hint:"Look for the property of a skewed time distribution.",steps:[{title:"Key idea",body:"Normal curve: symmetric, total area 1, tails endless in both directions (pp. 152–153)."},{title:"Apply to the stem",body:"A hard floor at zero is typical of cycle times, which are skewed, not normal (p. 154)."}],final:"Bounded at zero is NOT normal → answer **B**",whyWrong:["Incorrect — symmetry about the mean is a defining property of the normal curve.","","Incorrect — like every probability distribution, the normal curve has total area one.","Incorrect — the normal curve's tails approach the axis but never end."],bookRef:"Book pp. 152–154"},{id:"sv-2-1074",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:3,stem:"Converting a normally distributed variable into Z-scores does NOT change which of the following?",options:["The shape of the distribution","The mean of the distribution","The standard deviation of the distribution","The units in which the values are expressed"],answer:0,hint:"Standardising slides and rescales the curve.",steps:[{title:"Key idea",body:"Z subtracts the mean and divides by the SD (p. 152), giving mean 0, SD 1, no units."},{title:"Apply to the stem",body:"Shifting and rescaling keep the shape: normal data stay normal, skewed data stay skewed."}],final:"Shape is unchanged → answer **A**",whyWrong:["","Incorrect — after conversion the mean becomes 0.","Incorrect — after conversion the standard deviation becomes 1.","Incorrect — the units cancel, so Z-scores are unit-free."],trap:"Z-scores do not make non-normal data normal.",bookRef:"Book p. 152"},{id:"sv-2-1075",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:2,stem:"To which data set can the empirical rule NOT be applied directly?",options:["Strongly right-skewed repair times","Approximately normal shaft diameters","Approximately normal bottle fill weights","Handle times that passed a normality test"],answer:0,hint:"Which set breaks the rule's assumption?",steps:[{title:"Key idea",body:"The 68/95/99.7 shares come from the normal curve (p. 153)."},{title:"Apply to the stem",body:"Strongly skewed data put different shares inside ±1σ and ±2σ, so the rule does not apply."}],final:"Skewed data → NOT empirical rule → answer **A**",whyWrong:["","Incorrect — approximately normal data are exactly what the empirical rule describes.","Incorrect — fill weights that are approximately normal fit the 68/95/99.7 pattern.","Incorrect — data that fail to reject normality may be treated as normal for the rule."],bookRef:"Book pp. 153–154"},{id:"sv-2-1076",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:2,stem:"Which of these Measure activities does NOT require the data to be approximately normal?",options:["Estimating defects from Z and a standard normal table","Plotting the data on a time series plot","Calculating normal-based Cp and Cpk","Using the empirical rule to describe spread"],answer:1,hint:"Graphs show data; formulas assume shapes.",steps:[{title:"Key idea",body:"Many statistical tools assume normality in their calculations (p. 154)."},{title:"Apply to the stem",body:"A time series plot simply displays values in order; it makes no shape assumption."}],final:"Time series plot needs no normality → answer **B**",whyWrong:["Incorrect — Z-table areas come from the normal curve, so normality is required.","","Incorrect — normal-based capability indices assume normal data (p. 221).","Incorrect — the 68/95/99.7 rule is a property of normal data."],bookRef:"Book pp. 154, 167"},{id:"sv-2-1077",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:3,stem:"Which pattern on a normal probability plot does NOT indicate a departure from normality?",options:["Points forming an S-shape that bends away at both ends","Points forming a smooth bow away from the line","Points scattered tightly and randomly about the straight line","Points forming two straight groups with a jump between them"],answer:2,hint:"What does a normal sample look like on this plot?",steps:[{title:"Key idea",body:"Normal data fall on a straight line (p. 155); small random wobble is expected."},{title:"Eliminate look-alikes",body:"S-shape = tails, bow = skew, jump = mixture — all departures."}],final:"Tight random scatter on the line = normal → answer **C**",whyWrong:["Incorrect — an S-shape shows tails heavier or lighter than normal.","Incorrect — a bowed curve shows skewness.","","Incorrect — two groups with a jump suggest two mixed populations."],bookRef:"Book p. 155"},{id:"sv-2-1078",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:2,stem:"Which is NOT a recommended response in Measure when key data turn out to be non-normal?",options:["Stratify the data by shift, location or operator","Look for special causes by going to the process","Report baseline capability as observed performance","Stop the project, because the analysis cannot go further"],answer:3,hint:"The book's message is 'do not panic'.",steps:[{title:"Key idea",body:"Book pp. 157–158: non-normal data are not bad — stratify, look for special causes, use observed performance."},{title:"Apply to the stem",body:"Stopping the project is the one response the book rejects."}],final:"Stopping is NOT recommended → answer **D**",whyWrong:["Incorrect — stratifying is a recommended first step to reveal mixed streams.","Incorrect — the book advises going to the process rather than fighting the statistics.","Incorrect — observed performance is the book's method for non-normal data in Measure.",""],bookRef:"Book pp. 157–158, 221"},{id:"sv-2-1079",phase:2,topic:"2.2.3",qtype:"statements",difficulty:1,stem:`Which statements about the empirical rule for a normal distribution are CORRECT?

1. About 50% of values lie within ±1 standard deviation of the mean.
2. About 99.7% of values lie within ±2 standard deviations of the mean.
3. About 95% of values lie within ±2 standard deviations of the mean.
4. About 99.7% of values lie within ±3 standard deviations of the mean.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"68 – 95 – 99.7 for ±1, ±2, ±3.",steps:[{title:"Key idea",body:"Empirical rule (p. 153): ±1σ ≈ 68%, ±2σ ≈ 95%, ±3σ ≈ 99.7%."},{title:"Apply to the stem",body:"Statements 3 and 4 match; 1 and 2 misplace the figures."}],final:"3 and 4 are correct → answer **C**",whyWrong:["Incorrect — statement 1 is false (±1σ holds about 68%) and statement 2 is false (99.7% needs ±3σ).","Incorrect — statement 3 is true but statement 2 puts the 99.7% figure at ±2σ instead of ±3σ.","","Incorrect — statement 4 is true but statement 1 gives 50% instead of about 68% for ±1σ."],bookRef:"Book p. 153"},{id:"sv-2-1080",phase:2,topic:"2.2.3",qtype:"statements",difficulty:3,stem:`Which statements about reading a normal probability plot are CORRECT?

1. Data from a normal distribution fall close to a straight line.
2. An S-shaped pattern suggests tails that are heavier or lighter than normal.
3. A straight line shows that the process meets its specification limits.
4. A bowed pattern shows that the data are perfectly symmetric.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Straight = normal; the bend tells you how it is not normal.",steps:[{title:"Key idea",body:"Normal data plot as a straight line (p. 155); an S-shape = tail problem; a bow = skew."},{title:"Eliminate",body:"A straight line says nothing about the specification, so statement 3 is false; statement 4 reverses the meaning of a bow."}],final:"1 and 2 are correct → answer **A**",whyWrong:["","Incorrect — statement 2 is true, but statement 3 confuses normality with capability.","Incorrect — statement 3 confuses normality with capability, and a bowed pattern indicates skew, not symmetry.","Incorrect — statement 1 is true, but a bowed pattern indicates skewness, not perfect symmetry."],bookRef:"Book p. 155"},{id:"sv-2-1081",phase:2,topic:"2.2.3",qtype:"statements",difficulty:2,stem:`Which statements about the Anderson-Darling normality test are CORRECT?

1. A p-value of 0.02 means the data can be treated as normal.
2. The null hypothesis states that the data are normal.
3. A p-value above 0.05 leads to failing to reject the null hypothesis.
4. The test proves normality whenever the p-value is above 0.05.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"H₀ = normal; low p rejects it; high p fails to reject it.",steps:[{title:"Key idea",body:"Book pp. 155–156: H₀ is normal; p > 0.05 → fail to reject; p ≤ 0.05 → reject."},{title:"Apply to the stem",body:"Statements 2 and 3 follow the rule; 1 reverses it and 4 claims proof."}],final:"2 and 3 are correct → answer **B**",whyWrong:["Incorrect — statement 2 is true, but statement 1 reverses the rule: p = 0.02 rejects normality.","","Incorrect — statement 3 is true, but statement 4 over-claims: a test never proves H₀.","Incorrect — statement 1 reverses the decision rule and statement 4 claims proof."],bookRef:"Book pp. 155–156"},{id:"sv-2-1082",phase:2,topic:"2.2.3",qtype:"statements",difficulty:2,stem:`Which statements about non-normal data in the Measure phase are CORRECT?

1. Non-normal data often indicate special causes that can be found in the process.
2. Non-normal data mean that the project must be stopped.
3. Cycle times are usually symmetric because they cannot be negative.
4. Stratifying by shift or supplier can explain a non-normal pooled shape.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Non-normal is a clue; the zero bound causes skew.",steps:[{title:"Key idea",body:"Book pp. 154–158: non-normal data often reveal special causes; stratify; time is bounded at zero and skewed right."},{title:"Apply to the stem",body:"Statements 1 and 4 are true."}],final:"1 and 4 are correct → answer **D**",whyWrong:["Incorrect — statement 1 is true, but the book says non-normal data are not a reason to stop.","Incorrect — statement 2 is false, and statement 3 is false because the zero bound causes right skew.","Incorrect — statement 4 is true, but statement 3 is false: the zero bound makes cycle times skewed.",""],bookRef:"Book pp. 154–158"},{id:"sv-2-1083",phase:2,topic:"2.2.3",qtype:"true-false",difficulty:1,stem:"Many service and transactional processes produce data that are not normally distributed. True or False?",options:["True","False"],answer:0,hint:"Recall the book's warning about business processes.",steps:[{title:"Key idea",body:"Book p. 154: many processes in nature are normal, but **many business processes are not**."},{title:"Apply to the stem",body:"Time-based service metrics are typically skewed, so the statement is true."}],final:"True → answer **A**",whyWrong:["","Incorrect — the book stresses that many business processes, especially service ones, are not normal."],bookRef:"Book pp. 154, 157"},{id:"sv-2-1084",phase:2,topic:"2.2.3",qtype:"sequence",difficulty:3,stem:`Data that the team expected to be normal fail the normality test. Put these responses in the order the book suggests.

- **P** Go to the process to find the special causes behind each group or point
- **Q** Confirm the result with the probability plot and see where the departure is
- **R** Report the baseline as observed performance if the data are still non-normal
- **S** Stratify the data by time, location or operator`,options:["S → Q → R → P","Q → R → S → P","P → Q → S → R","Q → S → P → R"],answer:3,hint:"See it → split it → find it → report it.",steps:[{title:"Key idea",body:"Book pp. 157–158, 221: confirm with the plot, stratify, go to the process to find special causes, then use observed performance."},{title:"Apply to the stem",body:"Q, S, P, R."}],final:"Q → S → P → R → answer **D**",whyWrong:["Incorrect — the departure should be confirmed before stratifying, and reporting comes after the investigation.","Incorrect — reporting observed performance before stratifying skips the search for special causes.","Incorrect — going to the process first means not yet knowing where the data depart or which groups differ.",""],bookRef:"Book pp. 157–158, 221"},{id:"sv-2-1085",phase:2,topic:"2.2.3",qtype:"sequence",difficulty:2,stem:`Put these steps for estimating the proportion of output beyond an upper specification limit in order.

- **P** Look up the area beyond that Z value in the standard normal table
- **Q** Confirm that the data are approximately normal
- **R** Express the area as a percentage or as parts per million
- **S** Convert the specification limit into a Z-score`,options:["Q → S → P → R","S → P → R → Q","Q → P → S → R","S → Q → P → R"],answer:0,hint:"Check the model, then Z, then table, then report.",steps:[{title:"Key idea",body:"Book pp. 153, 221–223: check normality, compute Z, find the area, convert to % or PPM."},{title:"Apply to the stem",body:"Q, S, P, R."}],final:"Q → S → P → R → answer **A**",whyWrong:["","Incorrect — normality must be confirmed first; Z-table areas are meaningless for non-normal data.","Incorrect — the table is entered with a Z value, so Z must be calculated before the look-up.","Incorrect — calculating Z before checking normality risks using a model that does not fit."],bookRef:"Book pp. 221–223"},{id:"sv-2-1086",phase:2,topic:"2.2.3",qtype:"sequence",difficulty:1,stem:`Put these steps for standardising a single value in order.

- **P** Divide the difference by the standard deviation
- **Q** Interpret the result as a number of standard deviations from the mean
- **R** Subtract the mean from the value`,options:["P → R → Q","R → Q → P","R → P → Q","Q → R → P"],answer:2,hint:"Z = (value − mean) ÷ SD.",steps:[{title:"Key idea",body:"$Z = \\dfrac{x - \\mu}{\\sigma}$ (p. 152): subtract first, then divide."},{title:"Apply to the stem",body:"R (subtract), P (divide), Q (interpret)."}],final:"R → P → Q → answer **C**",whyWrong:["Incorrect — dividing the raw value by the SD first does not give the distance from the mean.","Incorrect — the difference cannot be read in standard deviations until it is divided by the SD.","","Incorrect — interpretation comes last, after Z has been calculated."],bookRef:"Book p. 152"},{id:"sv-2-1087",phase:2,topic:"2.2.3",qtype:"sequence",difficulty:2,stem:`Pooled repair times fail the normality test and the histogram shows two peaks. Put these investigation steps in order.

- **P** Test each group separately for normality
- **Q** Ask which X could split the data, such as crew or region
- **R** Notice the two peaks in the pooled histogram
- **S** Stratify the data by that X and graph each group`,options:["Q → R → S → P","R → Q → S → P","R → S → Q → P","R → Q → P → S"],answer:1,hint:"Notice → suspect → split → test.",steps:[{title:"Key idea",body:"Two peaks often mean two processes are mixed (p. 158); stratify to separate them (p. 159)."},{title:"Apply to the stem",body:"R, Q, S, P."}],final:"R → Q → S → P → answer **B**",whyWrong:["Incorrect — the question about which X splits the data comes from first noticing the two peaks.","","Incorrect — the data cannot be stratified until a candidate X has been chosen.","Incorrect — each group can be tested only after the data have been split into groups."],bookRef:"Book pp. 158–159"},{id:"sv-2-1088",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"A bottle-filling head slowly drifts upward during each shift and is reset at every shift change. What does the book suggest about the distribution of the fill weights?",options:["It will be normal, because fill weight is continuous data","It will be normal, because the head is reset every shift","It is unlikely to be normal, because the process has drifts and shifts","It cannot be judged, because fill weight is attribute data"],answer:2,hint:"The book lists the conditions under which output is normal.",steps:[{title:"Key idea",body:"Book p. 151: normal output needs only random error, no assignable causes, and **no drifts and shifts**."},{title:"Apply to the stem",body:"A drifting, reset head breaks that condition, so the pooled weights are unlikely to be normal."}],final:"Drifts and shifts → not normal → answer **C**",whyWrong:["Incorrect — continuous data can be non-normal; the drift adds a non-random pattern.","Incorrect — resetting creates repeated shifts, which the book lists as preventing normality.","","Incorrect — weight is continuous (variable) data, not attribute data."],bookRef:"Book p. 151"},{id:"sv-2-1089",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"In their own processes, a latency reading at Site A has **Z = 2.1** and a repair time at Site B has **Z = −3.2**. Which reading is more unusual?",options:["Site A, because its Z-score is positive","Neither, because readings in different units cannot be compared","Site A, because latency varies more than repair time","Site B, because it lies further from its mean in standard deviations"],answer:3,hint:"Compare the size of Z, ignoring the sign.",steps:[{title:"Key idea",body:"|Z| = distance from the mean in SDs; larger |Z| = rarer value."},{title:"Apply to the stem",body:"3.2 SDs is further out than 2.1 SDs, so Site B's reading is more unusual."}],final:"|−3.2| > |2.1| → Site B → answer **D**",whyWrong:["Incorrect — the sign shows the side of the mean, not how unusual the value is.","Incorrect — Z removes the units, which is exactly why it allows the comparison.","Incorrect — each Z already uses its own process variation; the size of Z is what matters.",""],bookRef:"Book p. 152"},{id:"sv-2-1090",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:3,stem:"A stable process produces normally distributed coating thicknesses. One reading falls **beyond the mean + 3σ**. What does the empirical rule suggest?",options:["Such a reading is expected about once in every three readings","Such a reading is very unlikely from random variation alone, so it should be investigated","Such a reading proves the measurement gauge is faulty","Such a reading means the data are no longer normal"],answer:1,hint:"How much of a normal distribution lies within ±3σ?",steps:[{title:"Key idea",body:"About 99.7% lie within ±3σ (p. 153), so values beyond it are very rare."},{title:"Apply to the stem",body:"A point that far out suggests a possible special cause worth checking."}],final:"Beyond 3σ → rare → investigate → answer **B**",whyWrong:["Incorrect — about one-third of readings lie beyond ±1σ, not beyond 3σ.","","Incorrect — a rare reading suggests a possible special cause; it proves nothing about the gauge.","Incorrect — a single point does not change the distribution's shape; it is a signal to investigate."],bookRef:"Book p. 153"},{id:"sv-2-1091",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"A Green Belt has four candidate metrics. Which one is MOST likely to be non-normal by its nature?",options:["Time to restore a failed broadband line, where many fixes take minutes and a few take days","Diameter of shafts turned on a stable lathe","Weight of cereal boxes from a well-controlled filler","Length of bolts cut on an automatic saw"],answer:0,hint:"Look for a metric with a hard floor and a long tail.",steps:[{title:"Key idea",body:"Time cannot be negative, so time data are bounded at zero and skewed right (p. 154)."},{title:"Apply to the stem",body:"Restore time has many short fixes and a long tail of slow ones."}],final:"Bounded time with long tail → non-normal → answer **A**",whyWrong:["","Incorrect — a machined dimension with only random variation is a classic normal measurement.","Incorrect — fill weight from a controlled process is typically approximately normal.","Incorrect — a cut length from a stable machine is usually approximately normal."],bookRef:"Book p. 154"},{id:"sv-2-1092",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"On a normal probability plot of 60 courier pick-up times, the points form a smooth **bow**, curving away from the straight line in one direction across the whole range. What does this MOST likely indicate?",options:["The data are skewed","The data contain one outlier","The data are recorded with too little resolution","The data come from two mixed processes"],answer:0,hint:"Different departures leave different fingerprints on the plot.",steps:[{title:"Key idea",body:"A bowed curve on a probability plot = skewness; an S-shape = tails; steps = granularity; jump = mixture."},{title:"Apply to the stem",body:"A smooth bow over the whole range → skewed (time data are often right-skewed, p. 154)."}],final:"Bow → skew → answer **A**",whyWrong:["","Incorrect — a single outlier shows as one point off the line, not a bow across the whole range.","Incorrect — poor resolution shows as stacked columns or steps of points.","Incorrect — a mixture usually shows as two groups or a dog-leg with a jump."],bookRef:"Book pp. 154–155"},{id:"sv-2-1093",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:3,stem:"Each call is recorded as **answered within 20 s: Yes / No**. A trainee wants to run an Anderson-Darling normality test on these results. Which statement is correct?",options:["The test is meaningful, because there are more than 100 calls","The test is meaningful, if Yes is coded as 1 and No as 0","The test is not meaningful, because Yes/No results are attribute data","The test is not meaningful, because AD needs fewer than 30 values"],answer:2,hint:"The normal curve models continuous data.",steps:[{title:"Key idea",body:"The normal distribution is a continuous model (p. 152); attribute data are non-normal by definition."},{title:"Apply to the stem",body:"Yes/No per call is attribute data, so testing it for normality makes no sense."}],final:"Attribute data → no normality test → answer **C**",whyWrong:["Incorrect — sample size cannot turn attribute data into continuous data.","Incorrect — coding gives only two values; a two-value variable cannot follow a normal curve.","","Incorrect — AD has no such upper limit; the problem is the data type."],bookRef:"Book pp. 152, 396"},{id:"sv-2-1094",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"A summary of 50 machined bore diameters shows mean = median = mode = 25.00 mm and a roughly symmetric histogram. What should the Green Belt conclude?",options:["The data are proven to be normal, so no test is needed","The data are bimodal, because three measures of centre agree","The data are right-skewed, because the mode is not above the mean","The data are consistent with normality, and an AD test should confirm it"],answer:3,hint:"Matching centre measures fit the normal curve — but evidence comes from a test.",steps:[{title:"Key idea",body:"In a normal curve mean = median = mode (p. 152), but normality is decided with AD and the plot (p. 155)."},{title:"Apply to the stem",body:"The summary is consistent with normality; confirm with the test before using normal tools."}],final:"Consistent → confirm with AD → answer **D**",whyWrong:["Incorrect — equal centre measures are consistent with normality but do not prove it.","Incorrect — agreement of the centre measures points to symmetry, not two peaks.","Incorrect — right skew puts the mean above the median and mode, which is not the case here.",""],bookRef:"Book pp. 152, 155"},{id:"sv-2-1095",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:3,stem:"For a normally distributed process, the lower specification limit has **Z = −1.2** and the upper limit has **Z = 3.1**. Which side contributes more out-of-specification output?",options:["The upper side, because its Z-value is larger","The lower side, because its limit is closer to the mean","Both sides equally, because the curve is symmetric","Neither side, because both Z-values are within ±3"],answer:1,hint:"Compare distances from the mean in SDs, ignoring the sign.",steps:[{title:"Key idea",body:"The closer a limit is to the mean (smaller |Z|), the larger the tail area beyond it (p. 153)."},{title:"Apply to the stem",body:"|−1.2| is much smaller than 3.1, so most defects fall below the LSL."}],final:"Smaller |Z| → bigger tail → lower side → answer **B**",whyWrong:["Incorrect — a larger Z puts the limit further out, leaving a smaller tail beyond it.","","Incorrect — the curve is symmetric, but the limits are at different distances from the mean.","Incorrect — 3.1 is beyond 3, and any limit at |Z| = 1.2 leaves a sizeable tail."],bookRef:"Book pp. 153, 222"},{id:"sv-2-1096",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:3,stem:'A colleague reports that the upper specification limit has **Z = 2** and writes "so 2% of output is out of specification". What should the Green Belt do?',options:["Look up the area beyond Z = 2 in the standard normal table and report that proportion","Accept the figure, because Z gives the percentage beyond the limit","Double the figure, because both tails must be counted","Recalculate Z using the median and the range"],answer:0,hint:"Z tells you where to enter the table.",steps:[{title:"Key idea",body:"Z = number of SDs from the mean; the proportion is the **area** read from the table (p. 153)."},{title:"Apply to the stem",body:"Report the table area beyond Z = 2, not '2%'."}],final:"Use the table area, not Z itself → answer **A**",whyWrong:["","Incorrect — Z is a distance in SDs, not a percentage; this repeats the error.","Incorrect — only the upper limit is involved, and the 2% figure itself is wrong.","Incorrect — Z is built from the mean and SD; the error is in reading Z, not calculating it."],trap:"Z read as a proportion is a known vendor mis-key.",bookRef:"Book pp. 152–153"},{id:"sv-2-1097",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:2,stem:"The Gage R&R for delivery-time recording is acceptable and a control chart shows the process is stable. Before calculating normal-based Cp and Cpk, what should the Green Belt do NEXT?",options:["Remove the longest delivery times from the data","Repeat the Gage R&R with more appraisers","Test the delivery times for normality","Set new specification limits from the data"],answer:2,hint:"Which assumption do normal-based capability indices rely on?",steps:[{title:"Key idea",body:"Always check normality before using a tool that assumes it, such as capability analysis (p. 221)."},{title:"Apply to the stem",body:"MSA and stability are done, so normality is the next prerequisite."}],final:"Next = normality test → answer **C**",whyWrong:["Incorrect — deleting data distorts capability and hides special causes.","Incorrect — the measurement system is already acceptable.","","Incorrect — specification limits come from the customer, not from process data."],bookRef:"Book p. 221"},{id:"sv-2-1098",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:3,stem:"A Green Belt calculated normal-based Cpk for heavily skewed repair times without checking normality, and reported the resulting PPM to the sponsor. Was this an appropriate action?",options:["Yes, because Cpk is valid for any distribution shape","Yes, because repair times are continuous data","No, because normal-based capability assumes the data are normal","No, because capability should be calculated only in the Control phase"],answer:2,hint:"Which assumption sits behind a normal-based PPM?",steps:[{title:"Key idea",body:"Many tools, including capability, assume normality; check it first (pp. 154, 221)."},{title:"Apply to the stem",body:"Skewed repair times break the assumption, so the PPM is unreliable."}],final:"Normality was skipped → No → answer **C**",whyWrong:["Incorrect — normal-based Cpk and PPM use normal-curve areas, so skewed data give wrong results.","Incorrect — being continuous does not make data normal; repair times are typically skewed.","","Incorrect — baseline capability is calculated in Measure; the error is the missing normality check."],bookRef:"Book pp. 154, 221"},{id:"sv-2-1099",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:2,stem:"Pooled cable-drum weights from **three suppliers** fail the Anderson-Darling test. What should the Green Belt do FIRST?",options:["Transform the pooled data until they pass the test","Conclude that the weighing scale is faulty","Collect a larger pooled sample and test again","Stratify the data by supplier and examine each group"],answer:3,hint:"Mixed sources often give a non-normal pool.",steps:[{title:"Key idea",body:"Stratify by time, location or operator — here, supplier (p. 159); non-normal data often hide special causes (p. 158)."},{title:"Apply to the stem",body:"Split by supplier first and look at each group's shape."}],final:"Stratify by supplier first → answer **D**",whyWrong:["Incorrect — transforming hides the supplier differences that probably cause the shape.","Incorrect — nothing points to the gauge; a mixed-source pool is the likely cause.","Incorrect — more pooled data repeat the same mixture and make AD even more sensitive.",""],bookRef:"Book pp. 158–159"},{id:"sv-2-1100",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:2,stem:"Handle-time data fail the normality test. To use normal-based tools, the Green Belt deletes the longest calls until the test is passed. Was this an appropriate action?",options:["Yes, because normal-based tools give more precise answers","Yes, because long calls are outliers by definition","No, because the long calls may reveal special causes worth investigating","No, because a normality test should be run only once on any data set"],answer:2,hint:"What does the book say non-normal data often contain?",steps:[{title:"Key idea",body:"Non-normal data are not bad and often point to special causes (pp. 157–158)."},{title:"Apply to the stem",body:"Deleting the long calls throws away the evidence and biases the baseline."}],final:"Data deleted to force normality → No → answer **C**",whyWrong:["Incorrect — precision means nothing if the data have been changed to fit the model.","Incorrect — long calls are not outliers by definition; they may be a real part of the process.","","Incorrect — retesting is allowed; the problem is deleting real data to force a result."],bookRef:"Book pp. 157–158"},{id:"sv-2-1101",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:3,stem:"Bore diameters from a lathe were expected to be normal, but the probability plot clearly departs from the line. No grouping factor is obvious in the data. What is the BEST next action?",options:["Treat the data as normal, because diameters are usually normal","Go to the process to look for the special causes behind the departure","Replace the probability plot with a histogram","Close the investigation, because non-normal data cannot be analysed"],answer:1,hint:"When data should be normal but are not …",steps:[{title:"Key idea",body:"Book p. 158: if the basic structure should be normal but is not, the data probably contain special causes."},{title:"Apply to the stem",body:"With no obvious stratifier, go and see the process (p. 221)."}],final:"Expected normal but not → go to the process → answer **B**",whyWrong:["Incorrect — the evidence says otherwise; ignoring it risks wrong capability results.","","Incorrect — a histogram adds no new evidence and is weaker for judging normality.","Incorrect — the book says non-normal data are not bad and can be analysed."],bookRef:"Book pp. 158, 221"},{id:"sv-2-1102",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:3,stem:"A probability plot of three months of daily ticket backlog shows a few extreme points at the top. The logbook shows they were the days of a major network outage. What is the BEST action?",options:["Treat the outage days as a special cause, analyse them separately and reassess the rest","Keep them in the baseline, because every data point must be used","Delete them without recording why, so the data look normal","Replace them with the average backlog"],answer:0,hint:"What does the book say about points linked to a known event?",steps:[{title:"Key idea",body:"Clusters or isolated points may be special causes; check the logbook, address them separately and exclude them from the baseline (p. 162)."},{title:"Apply to the stem",body:"Outage days are a documented special cause, so handle them on their own and reassess normality on the rest."}],final:"Known special cause → handle separately → answer **A**",whyWrong:["","Incorrect — known special causes should be addressed separately, not blended into the baseline.","Incorrect — exclusions must be justified and documented, not used to make data look normal.","Incorrect — inventing values distorts the data and hides the outage effect."],bookRef:"Book pp. 158, 162"},{id:"sv-2-1103",phase:2,topic:"2.2.3",qtype:"output",difficulty:1,stem:`A Green Belt reads a standard normal table excerpt:

\`\`\`
Standard Normal Distribution — area to the right of z
 z      Area
1.00   0.1587
1.50   0.0668
2.00   0.0228
2.50   0.0062
\`\`\`

The upper specification limit of a normal process has **z = 2.00**. What proportion of output is expected above the limit?`,options:["0.0062","0.0228","0.0668","0.1587"],answer:1,hint:"Enter the table with z and read the area.",steps:[{title:"Key idea",body:"The area to the right of z = the proportion beyond the upper limit (p. 153)."},{title:"Apply to the stem",body:"Row z = 2.00 → area 0.0228 (about 2.3%)."}],final:"z = 2.00 → 0.0228 → answer **B**",whyWrong:["Incorrect — 0.0062 is the area beyond z = 2.50, a limit further from the mean.","","Incorrect — 0.0668 is the area beyond z = 1.50.","Incorrect — 0.1587 is the area beyond z = 1.00, a limit only one SD from the mean."],bookRef:"Book pp. 153, 222"},{id:"sv-2-1104",phase:2,topic:"2.2.3",qtype:"output",difficulty:2,stem:`Minitab graphical summary of claim-processing times:

\`\`\`
Summary Report for Processing Time (days)
Anderson-Darling Normality Test
  A-Squared   3.84
  P-Value    <0.005
Mean        18.4      Minimum     2.1
StDev       11.9      1st Quartile  9.6
N            90       Median      14.2
                      3rd Quartile 24.8
                      Maximum     61.0
\`\`\`

Which conclusion is CORRECT?`,options:["The data are normal, because the mean and median are both positive","The data are not normal and are skewed to the left","The data are not normal and are skewed to the right","The data are normal, because A-squared is larger than the p-value"],answer:2,hint:"Check the p-value, then compare the mean with the median.",steps:[{title:"Key idea",body:"p ≤ 0.05 → reject H₀ → not normal (p. 155)."},{title:"Apply to the stem",body:"p < 0.005; mean 18.4 > median 14.2 and the maximum stretches to 61 → long right tail."}],final:"Not normal, right-skewed → answer **C**",whyWrong:["Incorrect — positive values say nothing about shape; the p-value rejects normality.","Incorrect — the mean is above the median and the maximum is far out, which is right skew.","","Incorrect — comparing A-squared with p is meaningless; p < 0.005 rejects normality."],bookRef:"Book pp. 154–155"},{id:"sv-2-1105",phase:2,topic:"2.2.3",qtype:"output",difficulty:2,stem:`Weld-strength data from four suppliers are tested for normality (α = 0.05):

\`\`\`
Normality Test (Anderson-Darling)
Supplier    N    Mean   StDev     AD   P-Value
Alpha      30   412.5   10.21   0.28    0.621
Beta       30   405.1    9.87   0.91    0.018
Gamma      30   409.8   11.04   0.34    0.479
Delta      30   398.6   14.66   1.37   <0.005
\`\`\`

Which statement is CORRECT?`,options:["Only the Alpha and Gamma data show significant evidence of non-normality","Only the Delta data show significant evidence of non-normality","All four suppliers' data can be treated as normal","Only the Beta and Delta data show significant evidence of non-normality"],answer:3,hint:"Compare each p-value with 0.05.",steps:[{title:"Key idea",body:"p ≤ α → reject normality; p > α → fail to reject (p. 155)."},{title:"Apply to the stem",body:"Beta 0.018 and Delta < 0.005 are below 0.05; Alpha and Gamma are above."}],final:"Beta and Delta non-normal → answer **D**",whyWrong:["Incorrect — this reverses the rule; Alpha and Gamma have p > 0.05 and fail to reject.","Incorrect — Beta also has p = 0.018, which is below 0.05.","Incorrect — Beta and Delta have p-values below 0.05, so normality is rejected for them.",""],bookRef:"Book p. 155"},{id:"sv-2-1106",phase:2,topic:"2.2.3",qtype:"output",difficulty:2,stem:`A team tests order-picking times before a capability study (α = 0.05):

\`\`\`
Normality Test: Pick Time (s)
Anderson-Darling
Mean      96.42
StDev     12.37
N            55
AD        0.732
P-Value   0.051
\`\`\`

Which conclusion is correct?`,options:["Reject H₀; the data are not normal","Accept H₀; the data are proven to be normal","No decision is possible, because p is close to α","Fail to reject H₀; the data may be treated as normal"],answer:3,hint:"Apply the rule exactly: p > α or p ≤ α?",steps:[{title:"Key idea",body:"p > 0.05 → fail to reject H₀ (normal) (p. 156)."},{title:"Apply to the stem",body:"0.051 > 0.05 → fail to reject → treat as normal."}],final:"0.051 > 0.05 → fail to reject → answer **D**",whyWrong:["Incorrect — 0.051 is above 0.05, so H₀ is not rejected, however close it is.","Incorrect — a test never proves or 'accepts' H₀; it fails to reject it.","Incorrect — the rule is applied as stated; p > α gives a clear decision.",""],trap:"'Accept H₀' is always a distractor.",bookRef:"Book p. 156"},{id:"sv-2-1107",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`Descriptive statistics for two variables from a call-centre study:

\`\`\`
Variable        N    Mean   StDev  Skewness  Kurtosis  AD P-Value
TalkTime_s    120   212.6   31.8     0.06     -0.21      0.583
HoldTime_s    120    41.3   27.9     0.11      3.87     <0.005
\`\`\`

Which statement is CORRECT?`,options:["HoldTime is non-normal, because it is strongly skewed","HoldTime is non-normal, with tails heavier than a normal curve","TalkTime is non-normal, because its kurtosis is negative","Both variables can be treated as normal"],answer:1,hint:"p-value first, then skewness for lopsidedness and kurtosis for tails.",steps:[{title:"Key idea",body:"Skewness ≈ 0 → symmetric; a large positive kurtosis → heavy tails and a sharp peak."},{title:"Apply to the stem",body:"HoldTime: p < 0.005 (not normal), skewness ≈ 0, kurtosis 3.87 → symmetric but heavy-tailed."}],final:"HoldTime non-normal, heavy tails → answer **B**",whyWrong:["Incorrect — HoldTime's skewness of 0.11 is near zero; its problem is the high kurtosis.","","Incorrect — a kurtosis of −0.21 is near zero, and its p-value of 0.583 fails to reject normality.","Incorrect — HoldTime has p < 0.005, so normality is rejected."],bookRef:"Book p. 155"},{id:"sv-2-1108",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`The team agreed to use **α = 0.10** for this normality check:

\`\`\`
Normality Test: Install Duration (min)
Anderson-Darling
Mean      138.6
StDev      22.4
N            48
AD        0.664
P-Value   0.074
\`\`\`

Which conclusion is correct?`,options:["Reject H₀; at α = 0.10 the data are treated as not normal","Fail to reject H₀, because 0.074 is above 0.05","Fail to reject H₀, because the AD statistic is below 1","Reject H₀, because the standard deviation is large"],answer:0,hint:"Compare p with the α the team actually chose.",steps:[{title:"Key idea",body:"Reject H₀ when p ≤ α (p. 155)."},{title:"Apply to the stem",body:"0.074 ≤ 0.10 → reject H₀ → not normal at this α."}],final:"0.074 ≤ 0.10 → reject → answer **A**",whyWrong:["","Incorrect — the agreed α is 0.10, not 0.05; the decision must use the stated α.","Incorrect — the decision is made on the p-value against α, not on the AD size.","Incorrect — the size of the SD says nothing about normality."],trap:"Do not default to 0.05 when a different α is stated.",bookRef:"Book p. 155"},{id:"sv-2-1109",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`Ticket first-response times before and after an auto-reply was introduced:

\`\`\`
Normality Test (Anderson-Darling)
Period    N    Mean   StDev  Minimum  Median    AD   P-Value
Before   80   46.2    9.8    21.0     45.7    0.29    0.608
After    80    3.1    2.6     0.0      2.2    4.95   <0.005
\`\`\`

The sponsor worries that the "After" data are no longer normal. What is the BEST response?`,options:["The improvement must be reversed, because normal data are required","The After data must contain a measurement error, because they changed shape","Non-normal After data are expected, because times piled up near zero; judge them against the project goal","The Before data should be used for all future analysis, because they are normal"],answer:2,hint:"What happens to the shape when a time metric gets close to its zero floor?",steps:[{title:"Key idea",body:"Time is bounded at zero and becomes right-skewed (p. 154); shape is judged against project intent."},{title:"Apply to the stem",body:"After: minimum 0.0, median 2.2 < mean 3.1 → skewed, exactly as expected after a big reduction."}],final:"Expected skew after improvement → answer **C**",whyWrong:["Incorrect — the book says there is no good or bad shape; the goal was faster response.","Incorrect — a shape change is the natural result of times pressing against zero.","","Incorrect — the Before data no longer describe the improved process."],bookRef:"Book pp. 154, 157"},{id:"sv-2-1110",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`Baseline data for time to first agent response on web chat:

\`\`\`
Descriptive Statistics: Response (min)
  N   Mean  StDev  Minimum    Q1  Median    Q3  Maximum
200   2.10   2.40     0.00  0.40    1.30  2.90    14.80
Anderson-Darling: AD = 6.82, P-Value < 0.005
Target: response within 5 min
\`\`\`

Which is the BEST approach for the Measure baseline?`,options:["Calculate the share beyond 5 minutes from Z using the mean and StDev","Remove the chats above Q3 so that the remaining data are normal","Report the observed share of chats answered later than 5 minutes","Use the empirical rule to state that 95% respond within mean ± 2 StDev"],answer:2,hint:"When the normal model fails, report what actually happened.",steps:[{title:"Key idea",body:"For capability in Measure, use observed performance unless the data are normal (p. 158)."},{title:"Apply to the stem",body:"p < 0.005, minimum 0 and a long right tail to 14.8 → count the actual share beyond 5 min."}],final:"Non-normal → observed performance → answer **C**",whyWrong:["Incorrect — the data are clearly non-normal, so normal-curve areas would be wrong.","Incorrect — deleting the slow chats removes exactly the problem the project must fix.","","Incorrect — the empirical rule applies only to approximately normal data."],bookRef:"Book pp. 154, 158"},{id:"sv-2-1111",phase:2,topic:"2.2.3",qtype:"output",difficulty:2,stem:`Before a capability study on bearing diameters (α = 0.05):

\`\`\`
Normality Test: Diameter (mm)
Anderson-Darling
Mean      20.004
StDev      0.011
N             75
AD         0.247
P-Value    0.743
LSL 19.970   USL 20.030
\`\`\`

Which statement is CORRECT?`,options:["The data are normal enough for a normal-based capability analysis","The process is capable, because the p-value is high","The process is in statistical control, because the AD value is small","The data must be transformed before any capability analysis"],answer:0,hint:"What exactly does a normality test decide?",steps:[{title:"Key idea",body:"p > 0.05 → fail to reject normality → normal-based tools may be used (p. 156)."},{title:"Eliminate look-alikes",body:"Capability and control are separate questions that this output cannot answer."}],final:"Normal enough → normal-based capability OK → answer **A**",whyWrong:["","Incorrect — p only judges the shape; capability is a separate comparison with the limits.","Incorrect — control is judged on a control chart in time order, not by AD.","Incorrect — p = 0.743 fails to reject normality, so no transformation is needed."],bookRef:"Book pp. 156, 221"},{id:"sv-2-1112",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which of these does the book give as an example of measurements that are approximately **normal**?",options:["Times to repair broken equipment","Counts of defects in each batch","Pass or fail results at inspection","Human heights and weights"],answer:3,hint:"The book's examples come from nature, not from service processes.",steps:[{title:"Key idea",body:"Book p. 152: many natural measurements, such as **heights and weights**, are approximately normal."},{title:"Eliminate look-alikes",body:"Repair times are skewed; counts and pass/fail results are discrete."}],final:"Heights and weights → answer **D**",whyWrong:["Incorrect — repair times are bounded at zero and usually skewed right.","Incorrect — defect counts are discrete and usually follow a Poisson distribution.","Incorrect — pass/fail results are attribute data and follow a binomial distribution.",""],bookRef:"Book p. 152"},{id:"sv-2-1113",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which Z-score belongs to a value exactly **three standard deviations above** the mean?",options:["−3","+3","+0.3","+99.7"],answer:1,hint:"Z counts standard deviations from the mean; the sign gives the side.",steps:[{title:"Key idea",body:"Z = number of SDs between the value and the mean (p. 152)."},{title:"Apply to the stem",body:"Three SDs above → Z = +3."}],final:"Three SDs above → +3 → answer **B**",whyWrong:["Incorrect — a negative Z places the value below the mean.","","Incorrect — +0.3 is less than one-third of a standard deviation above the mean.","Incorrect — 99.7% is the share of data within ±3σ, not a Z-score."],trap:"Do not mix up Z-values with the empirical-rule percentages.",bookRef:"Book p. 152"},{id:"sv-2-1114",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"Which Minitab output shows a histogram, the Anderson-Darling result and summary statistics on a single page?",options:["Graphical summary","Pareto chart","Gage run chart","Individuals chart"],answer:0,hint:"Minitab's 'Summary Report' bundles shape, test and statistics.",steps:[{title:"Key idea",body:"The graphical summary combines a histogram with a fitted curve, the AD test (A-squared and p-value) and statistics such as mean, SD and quartiles."},{title:"Eliminate look-alikes",body:"Pareto, gage run and individuals charts serve prioritising, MSA and stability."}],final:"Graphical summary → answer **A**",whyWrong:["","Incorrect — a Pareto chart ranks categories by frequency and shows no normality test.","Incorrect — a gage run chart displays MSA readings by part and operator.","Incorrect — an individuals chart is a control chart for stability over time."],bookRef:"Book pp. 155–156"},{id:"sv-2-1115",phase:2,topic:"2.2.3",qtype:"concept",difficulty:1,stem:"In a Minitab normality test, which printed value is compared with α to reach the decision?",options:["The AD statistic","The P-Value","The mean","The StDev"],answer:1,hint:"The decision rule is 'p versus α'.",steps:[{title:"Key idea",body:"p > α → fail to reject H₀ (normal); p ≤ α → reject H₀ (p. 155)."},{title:"Eliminate look-alikes",body:"AD, mean and StDev are printed too, but the decision uses only p."}],final:"Compare the P-Value with α → answer **B**",whyWrong:["Incorrect — the AD statistic measures misfit, but the decision rule uses the p-value.","","Incorrect — the mean locates the data; it plays no part in the normality decision.","Incorrect — the standard deviation measures spread, not departure from normality."],bookRef:"Book pp. 155–156"},{id:"sv-2-1116",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"Two data sets are shown on the same Minitab normal probability plot, with the data on the horizontal axis. Both follow straight lines, but the line for set B is clearly **flatter** than the line for set A. What does this indicate?",options:["Set B has the larger mean","Set B is less normal than set A","Set B has the larger standard deviation","Set B has more data points"],answer:2,hint:"A wider spread stretches the same percent range over more of the data axis.",steps:[{title:"Key idea",body:"With the data on the x-axis, a larger SD spreads the points over more values for the same percent range → a flatter line."},{title:"Eliminate look-alikes",body:"Position reflects the mean; straightness reflects normality."}],final:"Flatter line → larger SD → answer **C**",whyWrong:["Incorrect — the mean shifts a line sideways; it does not change its slope.","Incorrect — both sets follow straight lines, so both look normal; slope is not normality.","","Incorrect — sample size changes how many points are drawn, not the slope of the line."],bookRef:"Book p. 155"},{id:"sv-2-1117",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"What does choosing **α = 0.05** mean in an Anderson-Darling normality test?",options:["There is a 5% risk of concluding the data are normal when they are in fact non-normal","At least 95% of the data must lie within the specification limits","5% of the data points are allowed to be outliers","There is a 5% risk of concluding the data are non-normal when they are in fact normal"],answer:3,hint:"α is the risk of wrongly rejecting H₀.",steps:[{title:"Key idea",body:"α = probability of rejecting a true H₀ (Type I error). For AD, H₀ = data are normal."},{title:"Apply to the stem",body:"So α = 0.05 is a 5% risk of calling normal data non-normal."}],final:"α = risk of wrongly rejecting normality → answer **D**",whyWrong:["Incorrect — that is the β (Type II) risk, not α.","Incorrect — α is a decision risk; it has nothing to do with the specification.","Incorrect — α sets the risk of a wrong rejection, not a share of outliers.",""],bookRef:"Book pp. 155, 294"},{id:"sv-2-1118",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about the **standard normal distribution** is CORRECT?",options:["It can be used only when the process mean is zero","It gives correct areas for skewed data after conversion to Z","Its areas change with the units of the original data","Areas read from it apply to any normal process once the values are converted to Z"],answer:3,hint:"One reference curve, many processes.",steps:[{title:"Key idea",body:"Any normal distribution converts to the standard normal with Z (p. 152); the table then gives the area (p. 153)."},{title:"Eliminate look-alikes",body:"The conversion needs normal data but works for any mean and any units."}],final:"One table for every normal process → answer **D**",whyWrong:["Incorrect — any normal process can use it once its values are converted to Z.","Incorrect — converting to Z does not change the shape, so skewed data stay skewed.","Incorrect — Z is unit-free, so the same table serves every unit of measure.",""],bookRef:"Book pp. 152–153"},{id:"sv-2-1119",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about the **fitted line** on a Minitab normal probability plot is CORRECT?",options:["It shows the specification limits that the data must stay within","It shows the trend of the data over the time they were collected","It shows where the points would fall if the data were normal with the sample's mean and standard deviation","It shows the regression of the output on its most important input"],answer:2,hint:"The line is the 'expected' half of 'observed versus expected'.",steps:[{title:"Key idea",body:"The line is the normal distribution fitted with the data's own mean and SD; points on it behave as normal data would (p. 155)."},{title:"Eliminate look-alikes",body:"Specification, time trend and regression lines belong to capability, time series and regression graphs."}],final:"Fitted line = expected normal positions → answer **C**",whyWrong:["Incorrect — specification limits are not drawn on a probability plot.","Incorrect — trends over time are shown on a time series plot.","","Incorrect — a regression line relates a Y to an X on a fitted line plot."],bookRef:"Book p. 155"},{id:"sv-2-1120",phase:2,topic:"2.2.3",qtype:"concept",difficulty:3,stem:"Which statement about **stratifying** non-normal data is CORRECT?",options:["Each stratum can be close to normal even when the pooled data are not","If the pooled data are non-normal, every stratum must also be non-normal","Stratifying is useful only when the pooled data are already normal","Stratifying changes the values so that each group becomes normal"],answer:0,hint:"Think of two normal shifts with different averages poured into one histogram.",steps:[{title:"Key idea",body:"Mixed streams with different centres produce a non-normal (often bimodal) pool (p. 158)."},{title:"Apply to the stem",body:"Splitting by time, location or operator (p. 159) can reveal normal groups inside a non-normal pool."}],final:"Strata can be normal while the pool is not → answer **A**",whyWrong:["","Incorrect — mixing groups with different centres can make normal groups look non-normal when pooled.","Incorrect — stratifying is most useful exactly when the pooled shape is odd.","Incorrect — stratifying only separates the data into groups; no value is changed."],bookRef:"Book pp. 158–159"},{id:"sv-2-1121",phase:2,topic:"2.2.3",qtype:"concept",difficulty:2,stem:"Which statement about a **right-skewed** distribution is CORRECT?",options:["Its mean, median and mode are all equal","Its mean is pulled toward the long tail, so it is above the median","Its median is above its mean","Its long tail points toward the lower values"],answer:1,hint:"Extreme high values drag the mean, not the median.",steps:[{title:"Key idea",body:"The mean uses every value, so a long right tail pulls it upward; the median resists extremes."},{title:"Apply to the stem",body:"Right skew → mean > median, typical of times bounded at zero (p. 154)."}],final:"Right skew → mean above median → answer **B**",whyWrong:["Incorrect — equal centre measures belong to a symmetric (for example normal) distribution.","","Incorrect — a median above the mean describes a left-skewed distribution.","Incorrect — a tail toward lower values is left (negative) skew."],bookRef:"Book p. 154"},{id:"sv-2-1122",phase:2,topic:"2.2.3",qtype:"not-except",difficulty:3,stem:"Which is NOT a likely reason for an Anderson-Darling test to reject normality?",options:["Output from two shifts with different averages was pooled","The times are bounded at zero with a long right tail","The gauge reads in coarse steps, giving few distinct values","The process has a large standard deviation"],answer:3,hint:"Is spread the same thing as shape?",steps:[{title:"Key idea",body:"AD tests shape, comparing the data with a normal curve of the **same** mean and SD (p. 155)."},{title:"Apply to the stem",body:"A wide normal process still fits a wide normal curve; mixture, skew and granularity change the shape."}],final:"Large SD alone is NOT a cause of non-normality → answer **D**",whyWrong:["Incorrect — mixing streams with different centres is a classic cause of non-normal data.","Incorrect — a zero bound produces right skew, which AD detects.","Incorrect — poor resolution (granularity) stacks values and can make AD reject.",""],bookRef:"Book pp. 155, 158, 162"},{id:"sv-2-1123",phase:2,topic:"2.2.3",qtype:"output",difficulty:3,stem:`A Green Belt has only a few readings from a new cell site:

\`\`\`
Normality Test: Uplink Throughput (Mbps)
Anderson-Darling
Mean      41.75
StDev      6.92
N            12
AD        0.334
P-Value   0.452
\`\`\`

Which interpretation is BEST?`,options:["The data are proven normal, because the p-value is well above 0.05","Fail to reject H₀, but with so few values the test has little power, so use process knowledge as well","Reject H₀, because a sample of fewer than 30 values cannot be normal","The result is invalid, because AD needs at least 100 values"],answer:1,hint:"What can a test with only 12 values reliably detect?",steps:[{title:"Key idea",body:"p > 0.05 → fail to reject H₀ (p. 156); a fail-to-reject is weak evidence when N is small."},{title:"Apply to the stem",body:"N = 12: treat as normal enough, but confirm with process knowledge and more data."}],final:"Fail to reject, low power at N = 12 → answer **B**",whyWrong:["Incorrect — a high p-value never proves normality, least of all with 12 values.","","Incorrect — small samples can come from normal processes; N does not decide the shape.","Incorrect — AD can be run on small samples; N > 100 is the book's large-sample caution, not a minimum."],bookRef:"Book pp. 156–157"},{id:"sv-2-1124",phase:2,topic:"2.2.3",qtype:"best-action",difficulty:2,stem:"Time-to-restore data were non-normal. Following the book, the team stratified by fault type and found each fault type close to normal. The Green Belt then analysed each fault type separately. Was this an appropriate action?",options:["Yes, because stratifying separated different processes that had been mixed","Yes, because separate analysis guarantees that every group is capable","No, because data should always be analysed in one pooled set","No, because non-normal pooled data mean the strata cannot be used"],answer:0,hint:"What does a non-normal pool often hide?",steps:[{title:"Key idea",body:"Non-normal data often reveal mixed streams or special causes (p. 158); stratify by a relevant X (p. 159)."},{title:"Apply to the stem",body:"Each fault type behaves like its own process, so separate analysis is sound."}],final:"Stratified analysis is appropriate → Yes → answer **A**",whyWrong:["","Incorrect — stratifying explains the shape; it says nothing about capability against the target.","Incorrect — pooling different processes is what hid the structure in the first place.","Incorrect — strata can be normal even when the pool is not; that is why stratifying helps."],bookRef:"Book pp. 158–159"},{id:"sv-2-1125",phase:2,topic:"2.2.3",qtype:"sequence",difficulty:2,stem:`Put these Z-scores in order from the value **closest to the mean** to the value **furthest from the mean**.

- **P** Z = −2.4
- **Q** Z = 0.3
- **R** Z = 1.8
- **S** Z = −0.9`,options:["P → S → Q → R","Q → R → S → P","Q → S → R → P","P → R → S → Q"],answer:2,hint:"Distance from the mean is the size of Z, ignoring its sign.",steps:[{title:"Key idea",body:"|Z| = number of SDs from the mean; the sign only shows the side (p. 152)."},{title:"Apply to the stem",body:"Sizes 0.3, 0.9, 1.8, 2.4 → Q, S, R, P."}],final:"Q → S → R → P → answer **C**",whyWrong:["Incorrect — this orders the values from lowest to highest, not by distance from the mean.","Incorrect — this puts the positive values first; distance ignores the sign.","","Incorrect — this runs from furthest to closest, the reverse of the order asked."],bookRef:"Book p. 152"},{id:"sv-2-1126",phase:2,topic:"2.2.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

A distribution with a long tail stretching toward the higher values is described as positively [?].`,options:["bimodal","kurtotic","skewed","uniform"],answer:2,hint:"Positive or negative describes the direction of the longer tail.",steps:[{title:"Key idea",body:"Positive (right) skew = long tail toward high values, typical of cycle times (p. 154)."},{title:"Eliminate look-alikes",body:"Bimodal, kurtosis and uniform describe other shape features."}],final:"Positively skewed → answer **C**",whyWrong:["Incorrect — 'bimodal' describes a distribution with two peaks.","Incorrect — kurtosis describes peakedness and tail weight on both sides, not a one-sided tail.","","Incorrect — 'uniform' describes a flat distribution with no tail at all."],bookRef:"Book p. 154"},{id:"sv-2-1127",phase:2,topic:"2.2.3",qtype:"scenario",difficulty:2,stem:"On a normal probability plot of 70 repair costs, the points follow the line closely except at the **upper end**, where the highest values bend away to the right of the line. What does this MOST likely indicate?",options:["The upper tail is longer than a normal curve would predict","The lower tail is longer than a normal curve would predict","The data come from two mixed populations","The data are normal, because most points follow the line"],answer:0,hint:"The plot shows where the data depart, not just whether.",steps:[{title:"Key idea",body:"Points that bend away from the line show where the data differ from normal (p. 155)."},{title:"Apply to the stem",body:"High values larger than the line predicts → a long upper tail (right skew)."}],final:"Upper-end bend → long upper tail → answer **A**",whyWrong:["","Incorrect — the departure is at the upper end; the lower points follow the line.","Incorrect — a mixture usually shows as two groups or a jump in the middle of the plot.","Incorrect — a clear, systematic bend at one end is a departure, not chance."],bookRef:"Book p. 155"},{id:"sv-2-1128",phase:2,topic:"2.2.3",qtype:"true-false",difficulty:1,stem:"The Anderson-Darling test checks whether a process meets its specification limits. True or False?",options:["True","False"],answer:1,hint:"What does AD compare the data with?",steps:[{title:"Key idea",body:"AD is a goodness-of-fit test against a normal curve with the same mean and SD (p. 155)."},{title:"Apply to the stem",body:"Meeting the specification is a capability question, so the statement is false."}],final:"AD tests shape, not specs → False → answer **B**",whyWrong:["Incorrect — AD compares the data with a fitted normal curve; specification limits play no part in it.",""],bookRef:"Book p. 155"},{id:"sv-2-1129",phase:2,topic:"2.2.4",qtype:"concept",difficulty:1,stem:"Which graph BEST shows the shape, centre and spread of **500 continuous** fill-weight readings?",options:["Pareto chart","Histogram","Scatter plot","Time series plot"],answer:1,hint:"One continuous variable, many values, and the question is shape.",steps:[{title:"Key idea",body:"Book p. 160: a histogram shows **shape, centring and spread**, using equal intervals with bar height = frequency."},{title:"Apply to the stem",body:"500 values of one continuous variable → histogram."}],final:"Shape of one variable, large n → histogram → answer **B**",whyWrong:["Incorrect — a Pareto chart ranks categories of attribute data by frequency.","","Incorrect — a scatter plot shows the relationship between two continuous variables.","Incorrect — a time series plot shows values in production order to reveal patterns over time."],bookRef:"Book p. 160"},{id:"sv-2-1130",phase:2,topic:"2.2.4",qtype:"scenario",difficulty:1,stem:"A process engineer wants to see whether **oven temperature** is related to **coating thickness**, using 80 paired readings. Which graph should be used?",options:["Box plot","Histogram","Scatter plot","Pareto chart"],answer:2,hint:"Two continuous variables measured in pairs.",steps:[{title:"Key idea",body:"A scatter plot shows the relationship between two continuous variables — X across, Y up (p. 159)."},{title:"Apply to the stem",body:"Temperature (X) and thickness (Y) are both continuous → scatter plot."}],final:"Two continuous variables → scatter → answer **C**",whyWrong:["Incorrect — a box plot compares a continuous Y across categories, not two continuous variables.","Incorrect — a histogram shows the shape of one variable and cannot show a relationship.","","Incorrect — a Pareto chart ranks defect categories by frequency."],trap:"A pattern shows association, not proof of cause.",bookRef:"Book p. 159"},{id:"sv-2-1131",phase:2,topic:"2.2.4",qtype:"not-except",difficulty:2,stem:"Which graph is NOT suited to comparing the distributions of several groups side by side?",options:["Pareto chart","Box plot","Individual value plot","Dot plot by group"],answer:0,hint:"Which graph shows counts per category rather than distributions?",steps:[{title:"Key idea",body:"Box plots, individual value plots and grouped dot plots compare groups' centre, spread and outliers (pp. 162–166)."},{title:"Apply to the stem",body:"A Pareto chart ranks category frequencies; it does not show each group's distribution."}],final:"Pareto is NOT a group-distribution graph → answer **A**",whyWrong:["","Incorrect — side-by-side box plots are the standard way to compare groups.","Incorrect — an individual value plot shows every point for each group side by side.","Incorrect — a dot plot can be drawn for each group on a common scale."],bookRef:"Book pp. 162–166"},{id:"sv-2-1132",phase:2,topic:"2.2.4",qtype:"output",difficulty:2,stem:`Minitab box-plot statistics for handover delay (min) at one depot:

\`\`\`
Boxplot of Delay — Depot North
Q1            12.0
Median        16.5
Q3            21.0
Whisker low    6.0
Whisker high  33.0
Outliers (*)  41.0, 47.5
N             60
\`\`\`

What does the value 33.0 represent?`,options:["The maximum delay in the data","The upper outlier limit of Q3 + 1.5 × IQR","The upper quartile of the delays","The highest delay that is not an outlier"],answer:3,hint:"Where does a whisker stop when outliers exist?",steps:[{title:"Key idea",body:"Book p. 163: whiskers reach the lowest and highest values that are **not outliers**."},{title:"Apply to the stem",body:"41.0 and 47.5 are outliers, so the upper whisker ends at 33.0, the largest non-outlier."}],final:"Whisker high = largest non-outlier → answer **D**",whyWrong:["Incorrect — the maximum is 47.5, which is flagged as an outlier beyond the whisker.","Incorrect — the whisker stops at an actual data value inside that limit, not at the limit itself.","Incorrect — the upper quartile (Q3) is 21.0, the top of the box.",""],bookRef:"Book p. 163"},{id:"sv-2-1133",phase:2,topic:"2.2.4",qtype:"output",difficulty:2,stem:`Minitab descriptive statistics of call wrap-up time (s) for three teams:

\`\`\`
Descriptive Statistics: WrapUp by Team
Team    N   Median    IQR   Outliers
Red    40     52.0   14.0      0
Blue   40     49.5   31.5      2
Green  40     55.0    9.0      1
\`\`\`

In side-by-side box plots, which team would have the TALLEST box?`,options:["Green","Red","All three would be equal, because N is the same","Blue"],answer:3,hint:"The box spans Q1 to Q3, so its height is the IQR.",steps:[{title:"Key idea",body:"Box = Q1 to Q3 → box length = IQR (p. 163)."},{title:"Apply to the stem",body:"Blue has the largest IQR (31.5) → tallest box."}],final:"Largest IQR → Blue → answer **D**",whyWrong:["Incorrect — Green has the smallest IQR (9.0), so its box would be the shortest.","Incorrect — Red's IQR of 14.0 is smaller than Blue's 31.5.","Incorrect — box height is set by the IQR, not by the number of values.",""],bookRef:"Book p. 163"},{id:"sv-2-1134",phase:2,topic:"2.2.4",qtype:"concept",difficulty:2,stem:"On a box plot, how far can a whisker extend at most?",options:["To the smallest or largest value in the data, whatever its distance","To the specification limit on that side of the box","To the furthest data value that lies within 1.5 × IQR of the box","To a point three standard deviations from the median"],answer:2,hint:"Whiskers and the outlier rule use the same 1.5 × IQR fence.",steps:[{title:"Key idea",body:"Book p. 163: whiskers reach the lowest and highest values that are **not outliers**; outliers lie more than 1.5 × IQR beyond the box."},{title:"Apply to the stem",body:"So a whisker ends at the last real data value inside that fence."}],final:"Whisker = last value within 1.5 × IQR → answer **C**",whyWrong:["Incorrect — whiskers stop short of outliers; only data with no outliers reach the minimum and maximum.","Incorrect — specification limits are customer requirements and are not part of a box plot.","","Incorrect — box plots are built from quartiles and the IQR, not from standard deviations."],bookRef:"Book p. 163"},{id:"sv-2-1135",phase:2,topic:"2.2.4",qtype:"concept",difficulty:1,stem:"Which question is a **scatter plot** designed to answer?",options:["Does the output Y change as an input X changes?","Which category accounts for most of the defects?","Has the output shifted since a change was made?","Do the groups differ in centre and spread?"],answer:0,hint:"Two continuous variables, one on each axis.",steps:[{title:"Key idea",body:"A scatter plot shows the relationship between two continuous variables: X across, Y up (p. 159)."},{title:"Eliminate look-alikes",body:"Pareto = categories, time series = time, box plot = groups."}],final:"Scatter → Y versus X → answer **A**",whyWrong:["","Incorrect — ranking categories by frequency is the job of a Pareto chart.","Incorrect — a shift over time is seen on a time series plot or control chart.","Incorrect — comparing groups' centre and spread is the job of side-by-side box plots."],bookRef:"Book p. 159"},{id:"sv-2-1136",phase:2,topic:"2.2.4",qtype:"concept",difficulty:2,stem:"On a box plot, the median line sits close to Q1 and the upper whisker is much longer than the lower one. What does this suggest about the data?",options:["They are skewed to the left","They are skewed to the right","They are symmetric","They are bimodal"],answer:1,hint:"Where would the box plot of symmetric data put the median?",steps:[{title:"Key idea",body:"Book p. 163: symmetric data have the median near the middle of the box and similar whiskers."},{title:"Apply to the stem",body:"Bunched low values plus a long upper whisker → long right tail → right skew."}],final:"Median near Q1 + long upper whisker → right skew → answer **B**",whyWrong:["Incorrect — left skew puts the median near Q3 with a long lower whisker.","","Incorrect — symmetric data have the median near the middle of the box and whiskers of similar length.","Incorrect — a box plot cannot show two peaks; it can even hide them."],bookRef:"Book p. 163"},{id:"sv-2-1137",phase:2,topic:"2.2.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

A histogram that shows two distinct peaks is described as [?].`,options:["bimodal","granular","skewed","uniform"],answer:0,hint:"'Bi' means two.",steps:[{title:"Key idea",body:"Two peaks = **bimodal**, often a sign that two processes or populations are mixed (p. 158)."},{title:"Eliminate look-alikes",body:"Granular, skewed and uniform are other shape descriptions."}],final:"Two peaks = bimodal → answer **A**",whyWrong:["","Incorrect — 'granular' describes values stuck on a few levels because of limited resolution.","Incorrect — 'skewed' describes one peak with a longer tail on one side.","Incorrect — 'uniform' describes a flat shape with no peak."],bookRef:"Book pp. 158, 160"},{id:"sv-2-1138",phase:2,topic:"2.2.4",qtype:"statements",difficulty:2,stem:`Which statements about a histogram with **two distinct peaks** are CORRECT?

1. It proves that the process is out of statistical control.
2. It always comes from an error in the measurement system.
3. It often means that output from two process streams has been mixed.
4. Stratifying by a suspected X, such as shift or supplier, can separate the peaks.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Two peaks suggest two sources — how do you find them?",steps:[{title:"Key idea",body:"A bimodal shape often means two processes, shifts or suppliers are mixed (p. 158); stratify to separate them (p. 159)."},{title:"Apply to the stem",body:"Statements 3 and 4 are true; 1 and 2 over-claim."}],final:"3 and 4 are correct → answer **C**",whyWrong:["Incorrect — statement 1 over-claims (control needs a control chart) and statement 2 wrongly blames the gauge.","Incorrect — statement 3 is true, but statement 2 is false: two peaks usually come from the process, not the gauge.","","Incorrect — statement 4 is true, but statement 1 is false: shape alone cannot prove a lack of control."],bookRef:"Book pp. 158–159"},{id:"sv-2-1139",phase:2,topic:"2.2.4",qtype:"scenario",difficulty:1,stem:"A Green Belt wants a graph that flags unusually long handle times among 45 calls by applying a **fixed rule** rather than personal judgement. Which graph should be used?",options:["Histogram","Box plot","Pareto chart","Time series plot"],answer:1,hint:"Which graph marks points beyond a 1.5 × IQR fence?",steps:[{title:"Key idea",body:"Book p. 163: a box plot marks any point more than 1.5 × IQR beyond the box as an outlier (asterisk)."},{title:"Apply to the stem",body:"The rule is built into the graph, so no judgement is needed to flag the long calls."}],final:"Rule-based outliers → box plot → answer **B**",whyWrong:["Incorrect — a histogram shows long values as distant bars, but it applies no outlier rule.","","Incorrect — a Pareto chart ranks categories and does not flag individual values.","Incorrect — a time series plot shows order and patterns, not a rule-based outlier test."],bookRef:"Book pp. 162–163"},{id:"sv-2-1140",phase:2,topic:"2.2.4",qtype:"scenario",difficulty:3,stem:"Pooled call times showed two peaks. The team then drew side-by-side box plots by **call type** (billing, technical); each type is roughly symmetric and their medians are far apart. What does this BEST confirm?",options:["The two peaks came from poor gauge resolution","The call times are right-skewed because they are bounded at zero","The two peaks came from mixing two call types with different typical times","The billing calls contain outliers that should be deleted"],answer:2,hint:"What happens when two symmetric groups with different centres are pooled?",steps:[{title:"Key idea",body:"A bimodal pool often means two process streams are mixed (p. 158); box plots compare groups side by side (p. 162)."},{title:"Apply to the stem",body:"Separate, symmetric groups with distant medians → the pooled peaks were the two call types."}],final:"Two peaks = two call types mixed → answer **C**",whyWrong:["Incorrect — resolution problems show as stacked values, not as two groups with different medians.","Incorrect — each type is symmetric; the pooled shape came from the mixture, not from skew.","","Incorrect — nothing in the stem shows outliers; the difference is between the groups' centres."],bookRef:"Book pp. 158, 162"}];export{e as items};
